using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Security.Cryptography;
using System.Windows.Forms;
using ShareMeRowell;

class ZoroSkillChecks {
    static void Require(bool value,string message){if(!value)throw new Exception(message);}
    static IEnumerable<Control> All(Control root){foreach(Control c in root.Controls){yield return c;foreach(var child in All(c))yield return child;}}
    static object Field(object value,string name){return value.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(value);}
    static SoftButton Use(Form form){return All(form).OfType<SoftButton>().Single(c=>c.AccessibleName=="Use character skill");}
    static void Mastery(Form form){All(form).OfType<SoftButton>().Single(c=>c.AccessibleName=="Preview mastery outfit").PerformClick();Application.DoEvents();}
    static SoftButton Auto(Form form){return All(form).OfType<SoftButton>().Single(c=>c.AccessibleName=="Automatically use unlocked skills");}
    static void Select(Form form,int role){All(form).OfType<CharacterTile>().Single(c=>c.RoleIndex==role).PerformClick();Application.DoEvents();}
    static void Show(Form form){form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);form.Show();Application.DoEvents();}
    static void Snapshot(Form form,string path){Application.DoEvents();using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(path);}}
    static Bitmap Render(CharacterSkillScene scene,HeroProfile profile,int time){var image=new Bitmap(286,286);using(var g=Graphics.FromImage(image))scene.Draw(g,new Rectangle(0,0,286,286),profile,time,true);return image;}
    static string Digest(Bitmap image){using(var output=new MemoryStream()){image.Save(output,ImageFormat.Png);using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(output.ToArray()));}}
    static void Sample(CharacterSkillPreview skill,int position){((Timer)Field(skill,"clock")).Stop();var watch=(System.Diagnostics.Stopwatch)Field(skill,"time");var player=(SkillPlayback)Field(skill,"playback");long now=watch.ElapsedMilliseconds;player.Start(now,ZoroSequence.Duration);player.Update(now,true);player.Update(now+position,false);typeof(CharacterSkillPreview).GetMethod("Activity",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(skill,null);((Timer)Field(skill,"clock")).Stop();skill.Invalidate();}
    static void Seed(string folder,long xp){Directory.CreateDirectory(folder);using(var file=File.Create(Path.Combine(folder,"adventurer.receipts")))using(var sha=SHA256.Create()){
        var header=System.Text.Encoding.ASCII.GetBytes("SMXP001\n");file.Write(header,0,header.Length);int id=0;while(xp>0){int points=(int)Math.Min(50,xp);var payload=new byte[44];Array.Copy(BitConverter.GetBytes(++id),payload,4);Array.Copy(BitConverter.GetBytes(points*262144L),0,payload,32,8);Array.Copy(BitConverter.GetBytes(points),0,payload,40,4);file.Write(payload,0,payload.Length);var hash=sha.ComputeHash(payload);file.Write(hash,0,hash.Length);xp-=points;}file.Flush(true);
    }}
    [STAThread] static int Main(string[] args){try{
        Application.EnableVisualStyles();string folder=Path.GetFullPath(args[0]);Directory.CreateDirectory(folder);var checks=new List<string>();
        var bodies=new HashSet<int>();var effects=new HashSet<int>();for(int time=0;time<=2800;time++){var m=ZoroSequence.At(time);Require(m.Body>=0&&m.Body<72&&m.Guardian>=-1&&m.Guardian<24,"Zoro addressed a missing cel");Require(m.Eye==-1&&m.Closeup==0&&m.ActorScale==.54f,"Zoro introduced a close-up or camera zoom");bodies.Add(m.Body);if(m.Guardian>=0)effects.Add(m.Guardian);}Require(bodies.Count==72&&effects.Count==24&&ZoroSequence.At(2800).Complete,"Not all96 cels were reachable or the combo did not finish");foreach(int hit in new[]{870,1200,1920})Require(ZoroSequence.Impact(hit)==1,"A screen-slice impact was missing");Require(ZoroSequence.Impact(849)==0&&ZoroSequence.Impact(860)==.5f&&ZoroSequence.Finisher(1920)==1&&ZoroSequence.Finisher(2250)>0,"The instant onset or stronger final slice was lost");var player=new SkillPlayback();player.Start(0,ZoroSequence.Duration);player.Update(0,true);player.Update(2800,true);Require(!player.Running&&player.Position==2800,"Zoro used another character's duration");checks.Add("All96 cels are reachable in2.8seconds with72 body poses, three cut impacts and no zoom or face cut-in");
        var resources=typeof(CharacterSkillScene).Assembly.GetManifestResourceNames();Require(resources.Length==47&&!resources.Any(n=>n.Contains("zoro_eye")||n.Contains("source")||n.EndsWith(".gif")),"Unused source, zoom or review art was embedded");foreach(string asset in new[]{"ready","combo","finish","slashes"})using(var stream=typeof(CharacterSkillScene).Assembly.GetManifestResourceStream("ShareMeRowell.zoro_"+asset+".png"))using(var atlas=new Bitmap(stream)){
            int size=atlas.Width/4;Require(size==256&&atlas.Height==size*6,"Zoro atlas resolution or packing changed");for(int frame=0;frame<24;frame++){int visible=0;for(int y=0;y<size;y+=4)for(int x=0;x<size;x+=4)if(atlas.GetPixel(frame%4*size+x,frame/4*size+y).A>12)visible++;Require(visible>0||asset=="slashes"&&frame>=22,"An authored cel is empty");if(asset!="slashes"){int contacts=0;for(int edge=0;edge<size;edge++){int x=frame%4*size,y=frame/4*size;foreach(var colour in new[]{atlas.GetPixel(x,y+edge),atlas.GetPixel(x+size-1,y+edge),atlas.GetPixel(x+edge,y),atlas.GetPixel(x+edge,y+size-1)})if(colour.A>=180){contacts++;}}Require(contacts==0,"Art touches a tile boundary: "+asset+frame);}}
        }checks.Add("Four production atlases retain complete silhouettes and native256px detail with no clipped blade bands; the47-image allowlist excludes unused generations");
        string frames=Path.Combine(folder,"frames");Directory.CreateDirectory(frames);using(var scene=new CharacterSkillScene(13)){
            var profile=new HeroProfile{Role=13};var varied=new HeroProfile{Role=13,Look=1,Hair=5,Skin=4,HairColour=5,Shirt=3,Eyes=3,Element=5};var hashes=new HashSet<string>();foreach(int time in new[]{0,180,760,870,1200,1920,2500,2800})using(var image=Render(scene,profile,time)){hashes.Add(Digest(image));image.Save(Path.Combine(folder,"zoro-"+time+".png"));using(var alternate=Render(scene,varied,time))Require(Digest(image)==Digest(alternate),"Personal style altered a fixed sword move");}Require(hashes.Count==8,"The combo reused a still across action phases");
            foreach(int time in new[]{870,1200,1920})using(var image=new Bitmap(400,400))using(var g=Graphics.FromImage(image)){g.Clear(Color.Magenta);scene.Draw(g,new Rectangle(50,50,286,286),profile,time,true);foreach(var point in new[]{new Point(1,1),new Point(49,180),new Point(337,180),new Point(180,337)})Require(image.GetPixel(point.X,point.Y).ToArgb()==Color.Magenta.ToArgb(),"A sword slice escaped its preview card");}
            for(int time=0,index=0;time<=2800;time+=20,index++)using(var image=Render(scene,profile,time))image.Save(Path.Combine(frames,"frame-"+index.ToString("000")+".png"));profile.PixelPreview=true;using(var image=Render(scene,profile,1920))image.Save(Path.Combine(folder,"zoro-pixel.png"));
        }checks.Add("Native HD/Pixel renders show eye, swings, local split-screen cuts and recovery while keeping effects inside the card and fixed appearance intact");
        string state=Path.Combine(folder,"locked-profile");using(var store=new JourneyStore(state)){
            var p=store.Profile.Copy();p.Animations=true;p.MotionOverride=true;store.SaveProfile(p);using(var form=new AdventurerForm(store,()=>{})){
                Show(form);All(form).OfType<TextBox>().Single(c=>c.AccessibleName=="Search characters").Text="Zoro";Select(form,13);var skill=All(form).OfType<CharacterSkillPreview>().Single();Require(!skill.Running&&!Use(form).Visible,"Starter exposed a mastery skill");Use(form).PerformClick();Require(!skill.Running,"Starter button bypassed the mastery outfit");Mastery(form);Require(Use(form).Visible&&!skill.Running,"Locked mastery preview controls missing or auto-played");int forms=Application.OpenForms.Count;Use(form).PerformClick();Require(skill.Running&&skill.Visible&&Application.OpenForms.Count==forms,"Zoro did not activate in the existing card");Require(((Timer)Field(skill,"clock")).Interval==25,"Zoro did not use the quicker active drawing interval");Sample(skill,1200);Snapshot(form,Path.Combine(folder,"zoro-inline.png"));Require(store.Xp==0&&store.Profile.Role==0,"Manual Zoro awarded XP or equipped");foreach(var size in new[]{form.Size,form.MinimumSize}){form.Size=size;Application.DoEvents();foreach(var control in new Control[]{skill,Use(form),Auto(form)}){var bounds=new Rectangle(form.PointToClient(control.PointToScreen(Point.Empty)),control.Size);Require(form.ClientRectangle.Contains(bounds),"Zoro or his controls were clipped");}}Use(form).PerformClick();Require(!skill.Running&&((Control)Field(form,"hero")).Visible,"Stop did not restore the idle portrait");All(form).OfType<TextBox>().Single(c=>c.AccessibleName=="Search characters").Text="";Select(form,19);Use(form).PerformClick();Require(((Timer)Field(skill,"clock")).Interval==33,"Zoro changed another skill's timer");Select(form,13);Require(!skill.Running,"Changing characters left another movie running");form.Close();}
        }using(var store=new JourneyStore(state))Require(store.Xp==0&&store.Profile.Role==0,"Manual sword move changed saved progress");checks.Add("Manual Zoro stays in-card with25ms active drawing, stop, character switching and supported layouts without changing XP, equipment or other skill timing");
        string unlock=Path.Combine(folder,"unlock-profile");Seed(unlock,Adventure.Threshold(82)-1);using(var store=new JourneyStore(unlock)){
            Require(store.Level==81,"Zoro unlock fixture was incorrect");var p=store.Profile.Copy();p.Animations=true;p.MotionOverride=true;store.SaveProfile(p);using(var form=new AdventurerForm(store,()=>{})){Show(form);Select(form,13);Mastery(form);var skill=All(form).OfType<CharacterSkillPreview>().Single();Require(!skill.Running,"Locked mastery fixture auto-played");Require(store.AwardVerified(new FileMeta{name="isolated-zoro-unlock.bin",size=262144,sha256=new string('d',64)})==1,"Fixture award failed");form.RefreshProgress();Require(store.Level==82&&skill.Running&&store.Profile.Role==0,"The existing Level82 mastery did not activate once without equipping");Use(form).PerformClick();form.RefreshProgress();Require(!skill.Running,"Normal progress refresh replayed the combo");Select(form,0);Select(form,13);Require(skill.Running,"An unlocked mastery character did not auto-use");All(form).OfType<SoftButton>().Single(c=>c.AccessibleName=="Preview starter outfit").PerformClick();Require(!skill.Running&&!Use(form).Visible,"Starter started the mastery movie");Mastery(form);Require(skill.Running,"Unlocked mastery selection did not auto-use");Auto(form).PerformClick();Require(!skill.Running&&!store.Profile.AutoSkills,"Auto Off failed to stop and save");Use(form).PerformClick();Require(skill.Running,"Auto Off blocked manual use");form.Close();}
        }using(var store=new JourneyStore(unlock))Require(!store.Profile.AutoSkills&&store.Level==82&&store.Profile.Role==0,"Auto or genuine fixture progress changed on restart");checks.Add("The existing Level82 mastery gate activates once; starter stays idle and Auto Off retains manual demonstrations and saved state");
        using(var skill=new CharacterSkillPreview()){Require(!skill.Start(new HeroProfile{Role=13,Animations=false,MotionOverride=true}),"Zoro bypassed Animation Off");Require(!skill.Running&&!skill.Playing,"Rejected Zoro started a background timer");}Require(Adventure.RoleLevels[13]==28&&Adventure.MasteryLevel(13)==82&&!CharacterSkills.CanAutoUse(new HeroProfile(),13,81)&&CharacterSkills.CanAutoUse(new HeroProfile(),13,82)&&!CharacterSkills.HasForOutfit(13,28)&&CharacterSkills.HasForOutfit(13,82),"Zoro's unlock changed");checks.Add("Animation Off prevents sword playback and background work, while the original starter28 and mastery82 progression stays intact");
        File.WriteAllText(Path.Combine(folder,"result.json"),Wire.Encode(new{passed=checks.Count,checks=checks,artifactDirectory=folder,authoredFrames=96,bodyFrames=72,effectFrames=24,durationMilliseconds=2800,reviewFrames=141,reviewFrameDelayMilliseconds=20,noZoom=true,fixtureTimesUsed=true,phoneUsed=false,ownerProgressUsed=false,liveFocusForced=false}));Console.WriteLine(string.Join(Environment.NewLine,checks));return 0;
    }catch(Exception error){Console.Error.WriteLine(error);return 1;}}
}
